// Pick the files Flowscope needs. Never downloads .env files.
const repo = $('Get repo').first().json;
const tree = $input.first().json.tree || [];
const SKIP = /(^|\/)(node_modules|\.git|dist|build|\.next|\.vercel|coverage|vendor|venv|\.venv|__pycache__)\//;
const WANT = /(\.(m?[jt]sx?|cjs|json|toml|ya?ml|py|vue|svelte|astro|sql|jsonc)|(^|\/)requirements[^\/]*\.txt|(^|\/)\.env\.(example|sample|template))$/;
const SECRET_ENV = /(^|\/)\.env($|\.(?!example$|sample$|template$))/;
const files = tree
  .filter(f => f.type === 'blob' && WANT.test(f.path) && !SKIP.test(f.path) && !SECRET_ENV.test(f.path) && (f.size || 0) < 200000)
  .sort((a, b) => score(b.path) - score(a.path))
  .slice(0, 80);
function score(p) { return (/package\.json$/.test(p) ? 100 : 0) + (/\.env\./.test(p) ? 90 : 0) + (/^(src|app|api|lib|pages|server|supabase)\//.test(p) ? 20 : 0) - p.split('/').length; }
return files.map(f => ({ json: { path: f.path, raw: `https://raw.githubusercontent.com/${repo.full_name}/${repo.default_branch}/${f.path}` } }));

// Bundle the downloaded files for Flowscope and run a quick key check for the AI.
const picked = $('Pick files').all();
const repo = $('Get repo').first().json;
const files = $input.all().map((it, i) => ({ p: picked[i].json.path, t: String(it.json.data ?? '') }));
const KEYS = [/sk-(?:proj-)?[A-Za-z0-9_-]{24,}/, /[sr]k_live_[A-Za-z0-9]{16,}/, /AKIA[0-9A-Z]{16}/, /gh[pousr]_[A-Za-z0-9]{30,}/, /AIza[0-9A-Za-z_-]{35}/, /sk-ant-[A-Za-z0-9_-]{20,}/];
const quick = [];
for (const f of files) f.t.split('\n').forEach((ln, i) => { if (KEYS.some(r => r.test(ln))) quick.push(`Possible secret key in ${f.p} line ${i + 1}`); if (/(VITE_|NEXT_PUBLIC_|REACT_APP_)\w*(SECRET|SERVICE_ROLE|OPENAI|STRIPE_SECRET)/.test(ln)) quick.push(`Secret read in browser code: ${f.p} line ${i + 1}`); });
const pkg = files.find(f => /(^|\/)package\.json$/.test(f.p));
const envEx = files.find(f => /\.env\.(example|sample|template)$/.test(f.p));
return [{ json: {
  name: repo.name, repo: repo.full_name, branch: repo.default_branch, description: repo.description || '',
  files, fileCount: files.length, quick: quick.slice(0, 20),
  packageJson: pkg ? pkg.t.slice(0, 4000) : 'none',
  envNames: envEx ? envEx.t.split('\n').map(l => l.split('=')[0].trim()).filter(Boolean).join(', ') : 'none',
  paths: files.map(f => f.p).join('\n').slice(0, 4000)
} }];

