const pack = $('Package for Flowscope').first().json;
const lite = String($('Flowscope asks').first().json.body?.lite || '') === '1';
// lite=1 is for MCP clients: send the summary and file paths, not every file's contents.
return [{ json: { name: pack.name, repo: pack.repo, branch: pack.branch, ...(lite ? { paths: pack.files.map(f => f.p) } : { files: pack.files }), quick: pack.quick, summary: $json.output || '' } }];
